def regex_search(pattern: str, text: str) -> bool:
    if not pattern:
        return True

    pat = pattern
    m = len(pat)
    idx = 0

    def read_class_char():
        nonlocal idx
        if idx >= m:
            raise ValueError('unexpected end in character class')
        c = pat[idx]
        if c == '\\':
            idx += 1
            if idx >= m:
                raise ValueError('trailing backslash')
            c = pat[idx]
            idx += 1
            return c
        idx += 1
        return c

    def parse_class():
        nonlocal idx
        idx += 1
        neg = False
        if idx < m and pat[idx] == '^':
            neg = True
            idx += 1

        ranges = []
        while True:
            if idx >= m:
                raise ValueError('unclosed character class')

            c = pat[idx]
            if c == ']':
                if ranges:
                    idx += 1
                    ranges.sort()
                    merged = []
                    for lo, hi in ranges:
                        if merged and lo <= merged[-1][1] + 1:
                            merged[-1] = (merged[-1][0], max(hi, merged[-1][1]))
                        else:
                            merged.append((lo, hi))
                    return ('class', neg, merged)
                raise ValueError('empty character class')

            low = read_class_char()
            if idx < m and pat[idx] == '-' and idx + 1 < m and pat[idx + 1] != ']':
                idx += 1
                high = read_class_char()
                if ord(low) > ord(high):
                    raise ValueError('inverted character class range')
                ranges.append((ord(low), ord(high)))
            else:
                ranges.append((ord(low), ord(low)))

    def parse_atom():
        nonlocal idx
        if idx >= m:
            raise ValueError('unexpected end')

        c = pat[idx]
        if c == '(':
            idx += 1
            alts = parse_alternation('|)')
            if idx >= m or pat[idx] != ')':
                raise ValueError('unmatched (')
            idx += 1
            return ('group', alts)

        if c == '[':
            return parse_class()

        if c == '.':
            idx += 1
            return ('dot',)

        if c == '^':
            idx += 1
            return ('anchor', 'start')

        if c == '$':
            idx += 1
            return ('anchor', 'end')

        if c == '\\':
            idx += 1
            if idx >= m:
                raise ValueError('trailing backslash')
            ch = pat[idx]
            idx += 1
            return ('lit', ch)

        if c == ')':
            raise ValueError('unmatched )')

        idx += 1
        return ('lit', c)

    def parse_sequence(stop_chars: str) -> list:
        nonlocal idx
        elements = []
        while True:
            if idx >= m:
                break

            c = pat[idx]
            if c in stop_chars:
                break

            if c == ')':
                raise ValueError('unmatched )')

            if c == '*' or c == '+' or c == '?':
                if not elements:
                    raise ValueError('quantifier with no preceding element')
                last = elements[-1]
                if last[0] == 'anchor' or last[0] == 'rep':
                    raise ValueError('invalid quantifier placement')
                idx += 1
                elements.append(('rep', last, c))
            else:
                elements.append(parse_atom())

        return elements

    def parse_alternation(stop_chars: str) -> list:
        nonlocal idx
        alternatives = []
        while True:
            alternative = parse_sequence(stop_chars)
            alternatives.append(alternative)
            if idx >= m or pat[idx] != '|':
                break
            idx += 1
        return alternatives

    alternatives = parse_alternation('|')
    if idx != m:
        raise ValueError('pattern not fully consumed')

    EPS = 0
    CHAR = 1
    ASSERT = 2
    ACCEPT_STATE = 3

    state_type = []
    state_data = []

    def new_state(kind: int, data):
        state_type.append(kind)
        state_data.append(data)
        return len(state_type) - 1

    def add_eps(from_state: int, to_state: int):
        state_data[from_state].append(to_state)

    accept = new_state(ACCEPT_STATE, None)

    def compile_node(node):
        kind = node[0]

        if kind == 'lit':
            end = new_state(EPS, [])
            start = new_state(CHAR, (end, 0, ord(node[1])))
            return start, end

        if kind == 'dot':
            end = new_state(EPS, [])
            start = new_state(CHAR, (end, 1, None))
            return start, end

        if kind == 'class':
            _, neg, ranges = node
            end = new_state(EPS, [])
            start = new_state(CHAR, (end, 2, (neg, ranges)))
            return start, end

        if kind == 'anchor':
            end = new_state(EPS, [])
            assertion_kind = 0 if node[1] == 'start' else 1
            start = new_state(ASSERT, (end, assertion_kind))
            return start, end

        if kind == 'group':
            return compile_alternation(node[1])

        if kind == 'rep':
            _, inner, q = node
            b_start, b_end = compile_node(inner)
            start = new_state(EPS, [])
            end = new_state(EPS, [])

            if q == '*':
                add_eps(start, b_start)
                add_eps(start, end)
                add_eps(b_end, start)
            elif q == '+':
                add_eps(start, b_start)
                add_eps(b_end, start)
                add_eps(b_end, end)
            else:
                add_eps(start, b_start)
                add_eps(start, end)
                add_eps(b_end, end)

            return start, end

        raise ValueError('unknown node')

    def compile_alternation(alt_list):
        start = new_state(EPS, [])
        end = new_state(EPS, [])

        for alt in alt_list:
            if not alt:
                add_eps(start, end)
            else:
                s, e = compile_seq(alt)
                add_eps(start, s)
                add_eps(e, end)

        return start, end

    def compile_seq(elements):
        if not elements:
            start = new_state(EPS, [])
            end = new_state(EPS, [])
            add_eps(start, end)
            return start, end

        start, end = compile_node(elements[0])
        for element in elements[1:]:
            s2, e2 = compile_node(element)
            add_eps(end, s2)
            end = e2

        return start, end

    pattern_start, pattern_end = compile_alternation(alternatives)
    add_eps(pattern_end, accept)

    any_start = new_state(EPS, [])
    add_eps(any_start, pattern_start)

    text_len = len(text)

    def eps_closure(states, pos: int):
        stack = list(states)
        visited = set(states)

        while stack:
            st = stack.pop()
            typ = state_type[st]

            if typ == EPS:
                for nxt in state_data[st]:
                    if nxt not in visited:
                        visited.add(nxt)
                        stack.append(nxt)
            elif typ == ASSERT:
                target, a_kind = state_data[st]
                if (a_kind == 0 and pos == 0) or (a_kind == 1 and pos == text_len):
                    if target not in visited:
                        visited.add(target)
                        stack.append(target)

        return visited

    active = eps_closure({any_start}, 0)
    if accept in active:
        return True

    pos = 0
    for ch in text:
        code = ord(ch)
        nxt = {any_start}

        for st in active:
            typ = state_type[st]
            if typ == CHAR:
                target, test, payload = state_data[st]

                if test == 0:
                    if payload == code:
                        nxt.add(target)
                elif test == 1:
                    nxt.add(target)
                else:
                    neg, ranges = payload
                    inside = False
                    for lo, hi in ranges:
                        if lo <= code <= hi:
                            inside = True
                            break

                    if neg:
                        if not inside:
                            nxt.add(target)
                    else:
                        if inside:
                            nxt.add(target)

        pos += 1
        active = eps_closure(nxt, pos)
        if accept in active:
            return True

    return False
